159	    /**
160	     * The single derived key behind all duplicate detection: the normalized telephone, the
161	     * (lower-cased) email or an empty string when absent, and the household id or an empty string
162	     * when absent, joined with {@code '|'} (e.g. {@code +61412345678||H-3F5A9C2E}). Because the
163	     * telephone is part of the key, two owners are duplicates only when their WHOLE identity keys
164	     * are equal; two members of the same household (same {@code householdId}) with different
165	     * telephones have different identity keys and are therefore both allowed. The telephone and
166	     * email are already stored in their normalized forms on create, so this composes them directly.
167	     */
168	    @Transient
169	    public String getIdentityKey() {
170	        return (this.telephone == null ? "" : this.telephone) + "|"
171	            + (this.email == null ? "" : this.email) + "|"
172	            + (this.householdId == null ? "" : this.householdId);
