213	     *
214	     * @param name to test
215	     * @return true if pet name is already in use
216	     */
217	    public Pet getPet(String name, boolean ignoreNew) {
218	        name = name.toLowerCase();
219	        for (Pet pet : getPetsInternal()) {
220	            if (!ignoreNew || !pet.isNew()) {
221	                String compName = pet.getName();
222	                compName = compName.toLowerCase();
223	                if (compName.equals(name)) {
224	                    return pet;
225	                }
226	            }
227	        }
228	        return null;
229	    }
230	
231	    public Pet getPet(Integer petId) {
232	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
233	    }
