1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.E164Telephone;
13	import org.springframework.samples.petclinic.util.AddressNormalizer;
14	
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Map;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
30	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * Derive an owner's preferred contact channel from its stored contact details:
36	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
37	     */
38	    default String formatContactPreference(Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
43	        return hasEmail ? "EMAIL" : "PHONE";
44	    }
45	
46	    /**
47	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
48	     * (e.g. for owners created before the flag existed) to {@code false} so the response
49	     * always carries an explicit boolean.
50	     */
51	    default Boolean formatBulkSignupWarning(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
56	    }
57	
58	    /**
59	     * Known city-to-region mappings. Keyed by the exact city name, the canonical region
60	     * string is returned for a listed city and {@code "UNKNOWN"} for anything else.
61	     */
62	    Map<String, String> CITY_REGIONS = Map.of(
63	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
64	
65	    /**
66	     * Derive an owner's locality from its city using the fixed {@link #CITY_REGIONS}
67	     * city-to-region table, returning the canonical region string or {@code "UNKNOWN"}
68	     * when the city is {@code null} or not present in the table.
69	     */
70	    default String formatLocality(Owner owner) {
71	        if (owner == null) {
72	            return null;
73	        }
74	        return CITY_REGIONS.getOrDefault(owner.getCity(), "UNKNOWN");
75	    }
76	
77	    /**
78	     * Determine an owner's membership level, a number from {@code 1} to {@code 3} assigned on
79	     * create. It starts at {@code 1}, gains {@code 1} when an email address is present, and gains
80	     * {@code 1} when the owner has no namesakes (its {@code namesakeCount} is {@code 0}), capped at
81	     * {@code 3}. A null or absent namesake count is treated as not being zero, so it contributes
82	     * nothing. Level {@code 4} is reserved for tenure.
83	     */
84	    default Integer formatMembershipLevel(Owner owner) {
85	        if (owner == null) {
86	            return null;
87	        }
88	        int level = 1;
89	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
90	        if (hasEmail) {
91	            level++;
92	        }
93	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
94	        if (uniqueName) {
95	            level++;
96	        }
97	        return Math.min(level, 3);
98	    }
99	
100	    /**
101	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
102	     * is the last two digits of the registration date year (e.g. {@code "TOW-SMI-0007-M26"}).
103	     * Returns {@code null} when either the customer code or registration date is absent, since
104	     * the number cannot be derived without both.
105	     */
106	    default String formatMembershipNumber(Owner owner) {
107	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
108	            return null;
109	        }
110	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
111	    }
112	
113	    /**
114	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
115	     */
116	    default String formatDisplayName(Owner owner) {
117	        if (owner == null) {
118	            return null;
119	        }
120	        return owner.getLastName() + ", " + owner.getFirstName();
121	    }
122	
123	    /**
124	     * Format an owner's initials as the upper-cased first letters of the first and last
125	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
126	     */
127	    default String formatInitials(Owner owner) {
128	        if (owner == null) {
129	            return null;
130	        }
131	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
132	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
